  folioId?: string;
  criteria: RubricCriterion[];
  overallScore: number;
  overallGrade: string;
  summary: string;
  timestamp: number;
  /** Per-persona judge scores, 0-10. */
  judges: import("../utils/rubric").JudgeResult[];
  /** Static-feature breakdown (length, pacing, evidence, …). */
  staticScore: import("../utils/rubric").StaticScore;
