import { describe, expect, test } from "bun:test";
import {
  calculateJwkThumbprint,
  exportJWK,
  generateKeyPair,
  SignJWT,
} from "jose";
import { createGateway } from "./app";
import type { RealtimeUpgradeContext } from "./realtime";
import type { AccountEvolutionService } from "./account-evolution";
import type {
  CapabilityClaims,
  GatewayConfig,
  AccountSyncKeyRegistry,
  ProjectExecutionConfigRegistry,
  CiRunRegistry,
  ProviderStore,
  SandboxRunRecord,
  SandboxRunRegistry,
  StoredResponse,
} from "./types";
import { ProjectExecutionConfigSchema } from "@notorganic/contracts";
import type { CiRun, ProjectExecutionConfig } from "@notorganic/contracts";

const signingKey = new TextEncoder().encode("gateway-key".padEnd(32, "!"));
const gatewayKeys = await generateKeyPair("EdDSA", { extractable: true });
const gatewayPrivateJwk = await exportJWK(gatewayKeys.privateKey);
const gatewayPublicJwk = await exportJWK(gatewayKeys.publicKey);

function mockStore(overrides: Partial<ProviderStore> = {}): ProviderStore {
  return {
    reserve: async ({ requestId }) => ({ requestId, status: "reserved" }),
    markDispatched: async () => {},
    markAccepted: async () => {},
    settle: async () => {},
    settleWithResponse: async () => {},
    release: async () => {},
    reconcile: async () => {},
    getResponse: async () => null,
    putEncryptedResponse: async () => {},
    deleteResponse: async () => false,
    listInputItems: async () => ({ object: "list", data: [] }),
    getAccount: async () => ({ id: "did:plc:alice" }),
    getWallet: async () => ({ balance_microusd: 100 }),
    listUsage: async () => ({ object: "list", data: [] }),
    createCheckout: async () => ({ url: "https://billing.test/session" }),
    hasRealtimeConsent: async () => false,
    consumeDpopProof: async () => true,
    ...overrides,
  };
}

function config(
  store: ProviderStore,
  upstream: NonNullable<GatewayConfig["fetch"]> = async () => Response.json({}),
): GatewayConfig {
  return {
    store,
    gatewayIssuer: "https://gateway.test",
    gatewayAudience: "notorganic",
    gatewaySigningPrivateJwk: gatewayPrivateJwk,
    gatewaySigningPublicJwk: gatewayPublicJwk,
    portkeyApiKey: "pk-secret",
    portkeyBaseUrl: "https://portkey.test/v1",
    pseudonymSecret: signingKey,
    defaultMaxCostMicrousd: 1_000_000,
    fetch: upstream,
  };
}

describe("GPT-Live route", () => {
  const liveHeaders = {
    upgrade: "websocket",
    "idempotency-key": "live-test",
    "x-notorganic-max-cost-microusd": "100000",
  };

  test("auth, scope, consent, configuration and wallet gate the new path", async () => {
    for (const scenario of [
      "auth",
      "scope",
      "consent",
      "disabled",
      "budget",
      "upgrade",
      "wallet",
    ] as const) {
      let upgraded = false;
      let reserved = false;
      const cfg = config(
        mockStore({
          hasRealtimeConsent: async () => scenario !== "consent",
          reserve: async ({ requestId }) => {
            reserved = true;
            if (scenario === "wallet") throw new Error("wallet rejected");
            return { requestId, status: "reserved" };
          },
        }),
      );
      if (scenario !== "disabled")
        cfg.live = {
          apiKey: "server-only-secret",
          upstreamMicrousdPerSecond: 100,
        };
      const app = createGateway(cfg, {
        realtime: {
          upgrade: () => {
            upgraded = true;
            return new Response(null, { status: 204 });
          },
        },
      });
      const headers = {
        ...liveHeaders,
        ...(scenario === "budget"
          ? { "x-notorganic-max-cost-microusd": "1" }
          : {}),
        ...(scenario === "upgrade" ? { upgrade: "" } : {}),
      };
      const req =
        scenario === "auth"
          ? new Request("https://gateway.test/v1/live/sessions", { headers })
          : await authorizedRequest(
              "/v1/live/sessions",
              { headers },
              scenario === "scope" ? "wallet:read" : "realtime:connect",
            );
      const response = await app.fetch(req);
      expect(response.status).toBeGreaterThanOrEqual(400);
      expect(upgraded).toBe(false);
      expect(reserved).toBe(scenario === "wallet");
      expect(await response.text()).not.toContain("server-only-secret");
    }
  });

  test("uses the new upstream path, attributes Live separately and settles once", async () => {
    let context!: RealtimeUpgradeContext;
    const settlements: unknown[] = [];
    const cfg = config(
      mockStore({
        hasRealtimeConsent: async () => true,
        reserve: async (input) => {
          expect(input.feature).toBe("live");
          expect(input.requestHash).toBe("live");
          expect(input.accountId).toBe("did:plc:alice");
          return { requestId: input.requestId, status: "reserved" };
        },
        settle: async (input) => {
          settlements.push(input);
        },
      }),
    );
    cfg.live = { apiKey: "server-only-secret", upstreamMicrousdPerSecond: 100 };
