async function authorizedRequest(
  path: string,
  init: RequestInit,
  scope: string,
  subject = "did:plc:alice",
  product:
    | "twyne"
    | "keating"
    | "interleave"
    | "stich"
    | "notorganic" = "twyne",
): Promise<Request> {
  const { publicKey, privateKey } = await generateKeyPair("ES256");
  const jwk = await exportJWK(publicKey);
  const jkt = await calculateJwkThumbprint(jwk);
  const token = await new SignJWT({
    typ: "notorganic/access+jwt",
    product,
    assertion_jti: "assertion-123",
    token_type: "user",
    session_version: 1,
    capabilities: [scope],
    cnf: { jkt },
    max_cost_microusd: 1_000_000,
  } satisfies Omit<CapabilityClaims, keyof import("jose").JWTPayload>)
    .setProtectedHeader({ alg: "EdDSA" })
    .setIssuer("https://gateway.test")
    .setSubject(subject)
    .setAudience("notorganic")
    .setIssuedAt()
    .setExpirationTime("5m")
    .setJti(crypto.randomUUID())
    .sign(gatewayKeys.privateKey);
  const url = `https://gateway.test${path}`;
  const method = init.method ?? "GET";
  const ath = Buffer.from(
    new Uint8Array(
      await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token)),
    ),
  ).toString("base64url");
  const dpop = await new SignJWT({ htm: method, htu: url, ath })
    .setProtectedHeader({ alg: "ES256", typ: "dpop+jwt", jwk })
    .setIssuedAt()
    .setJti(crypto.randomUUID())
    .setExpirationTime("1m")
    .sign(privateKey);
  const headers = new Headers(init.headers);
  headers.set("authorization", `DPoP ${token}`);
  headers.set("dpop", dpop);
  return new Request(url, { ...init, headers });
}

