export interface JudgementQuestion {
  type: "noul" | "choice" | "score";
  instructions: string;
  criteria?: string[];
}

/** Local development means a loopback Convex runtime, never a hosted deployment. */
export function directJudgementKey(env: Record<string, string | undefined>): string | null {
  const key = env.TYPESAFE_API_KEY?.trim();
  if (!key) return null;
  try {
    const url = new URL(env.CONVEX_CLOUD_URL || env.CONVEX_SITE_URL || "");
    return ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname) ? key : null;
  } catch {
    return null;
  }
}

/** Keep the app's ordered labels, emit the current HTTP Choice map contract. */
export function judgementQuestions(questions: Record<string, JudgementQuestion>) {
  const entries = Object.entries(questions);
  if (!entries.length || entries.length > 64) throw new Error("question limit");
  const normalized = Object.fromEntries(entries.map(([id, q]) => {
    if (!q.instructions.trim()) throw new Error("missing instructions");
    if (q.type === "noul") return [id, { type: q.type, instructions: q.instructions }];
    const options = q.criteria ?? [];
    if (options.length < 2 || options.length > 64 || options.some((value) => !value.trim()) || new Set(options).size !== options.length) {
      throw new Error("invalid criteria");
    }
    return [id, { type: q.type, instructions: q.instructions, criteria: q.type === "choice" ? Object.fromEntries(options.map((value) => [value, null])) : options }];
  }));
  if (JSON.stringify(normalized).length > 96_000) throw new Error("question limit");
  return normalized;
}

export function validJudgementResponse(value: unknown, questions: Record<string, JudgementQuestion>): value is {
  model: string;
  answers: Record<string, unknown>;
  usage: { input_tokens: number; output_tokens: number };
} {
  if (!value || typeof value !== "object") return false;
  const p = value as Record<string, unknown>;
  if (typeof p.model !== "string" || !p.answers || typeof p.answers !== "object" || Array.isArray(p.answers)) return false;
  const usage = p.usage as Record<string, unknown> | undefined;
  if (!usage || ![usage.input_tokens, usage.output_tokens].every((n) => typeof n === "number" && Number.isSafeInteger(n) && n >= 0)) return false;
  return Object.entries(questions).every(([id, q]) => {
    const a = (p.answers as Record<string, Record<string, unknown>>)[id];
