import {
  $,
  component$,
  useStore,
  useStylesScoped$,
  useVisibleTask$,
} from "@qwik.dev/core";
import { Link } from "@qwik.dev/router";
import { api } from "../../../convex/_generated/api";
import { useConvexClient } from "../../utils/convex-context";
import {
  loadActiveFolioIdFromIdb,
  loadBriefFromIdb,
  loadFolioContentFromIdb,
  loadFoliosFromIdb,
} from "../../utils/idb";
import { loadPersonaNotesLocally } from "../../utils/convex-sync";
import { loadRevisionHistory } from "../../utils/revision-history";
import {
  emptyWritingToolsNotebook,
  loadWritingToolsNotebook,
  saveWritingToolsNotebook,
  type WritingToolsNotebook,
} from "../../utils/writing-tools-storage";
import {
  WRITING_LENSES,
  runWritingLens,
  type WritingLensId,
  type WritingLensInput,
  type WritingLensResult,
} from "../../utils/writing-lenses";

interface ToolsState {
  loaded: boolean;
  folioId: string;
  folioName: string;
  draft: string;
  revisions: { id: string; text: string; label: string }[];
  notes: { id: string; text: string; author: string }[];
  notebook: WritingToolsNotebook;
  lens: WritingLensId;
  previousId: string;
  currentId: string;
  focus: string;
  newPassage: string;
  claim: string;
  previousClaim: string;
  source: string;
  busy: boolean;
  saving: boolean;
  saveNotice: string;
  error: string;
  result: WritingLensResult | null;
  resultKey: string;
  stale: boolean;
}

/** Runs only in the browser; retain paragraph boundaries for the reader lens. */
function manuscriptText(html: string): string {
  const document = new DOMParser().parseFromString(html, "text/html");
  document.querySelectorAll("script,style").forEach((node) => node.remove());
  document
    .querySelectorAll("p,h1,h2,h3,h4,h5,h6,li,blockquote,div,br")
    .forEach((node) => node.append("\n\n"));
  return (document.body.textContent ?? "")
    .replace(/[ \t]+/g, " ")
    .replace(/\n\s*\n/g, "\n\n")
    .trim();
}

function inputs(state: ToolsState): WritingLensInput {
  const comparesRevisions = state.lens === "revision" || state.lens === "voice";
  return {
    draft:
      !comparesRevisions || state.currentId === "current"
        ? state.draft
        : (state.revisions.find((revision) => revision.id === state.currentId)
            ?.text ?? ""),
    audience: state.notebook.audience,
    ...(comparesRevisions
      ? {
          previousDraft: state.revisions.find(
            (revision) => revision.id === state.previousId,
          )?.text,
        }
      : {}),
    ...(state.lens === "voice"
      ? { voiceSamples: state.notebook.voiceSamples }
      : {}),
    ...(state.lens === "scraps"
      ? { scraps: state.notebook.scraps, focus: state.focus }
      : {}),
    ...(state.lens === "room" ? { notes: state.notes } : {}),
    ...(state.lens === "circling"
      ? {
          revisions: [...state.revisions]
            .reverse()
            .map(({ id, text }) => ({ id, text })),
          focus: state.focus,
        }
      : {}),
    ...(state.lens === "research" ? { sources: state.notebook.sources } : {}),
    ...(state.lens === "promises"
      ? { intentionalPromises: state.notebook.intentionalPromises }
      : {}),
  };
}

function inputKey(state: ToolsState): string {
  return JSON.stringify([state.folioId, state.lens, inputs(state)]);
}

function materialPreview(state: ToolsState): string {
  const input = inputs(state);
  const sections = [`Draft\n${input.draft}`];
  if (input.audience) sections.push(`Intended reader\n${input.audience}`);
  if (input.previousDraft) sections.push(`Earlier revision\n${input.previousDraft}`);
  if (input.focus) sections.push(`Your focus\n${input.focus}`);
  for (const [index, passage] of (input.voiceSamples ?? []).entries()) sections.push(`Voice example ${index + 1}\n${passage.text}`);
  for (const [index, passage] of (input.scraps ?? []).entries()) sections.push(`Saved scrap ${index + 1}\n${passage.text}`);
  for (const note of input.notes ?? []) sections.push(`Room note · ${note.author || "Editor"}\n${note.text}`);
  for (const [index, revision] of (input.revisions ?? []).entries()) sections.push(`Checkpoint ${index + 1} (oldest first)\n${revision.text}`);
  for (const [index, pair] of (input.sources ?? []).entries()) sections.push(`Source pair ${index + 1}\nCurrent claim: ${pair.claim}${pair.previousClaim ? `\nEarlier wording: ${pair.previousClaim}` : ""}\nSource excerpt: ${pair.source}`);
  return sections.join("\n\n———\n\n");
}

export const WritingTools = component$(() => {
  const client = useConvexClient();
  const state = useStore<ToolsState>({
    loaded: false,
    folioId: "",
    folioName: "",
    draft: "",
    revisions: [],
    notes: [],
    notebook: emptyWritingToolsNotebook(),
    lens: "revision",
    previousId: "",
    currentId: "current",
    focus: "",
    newPassage: "",
    claim: "",
    previousClaim: "",
    source: "",
    busy: false,
    saving: false,
    saveNotice: "",
    error: "",
    result: null,
    resultKey: "",
    stale: false,
  });

  const refresh = $(async () => {
    const folioId = await loadActiveFolioIdFromIdb();
    if (!folioId) {
      state.folioId = "";
      state.draft = "";
      state.result = null;
      state.loaded = true;
      return;
    }
    const [html, revisions, notes, folios] = await Promise.all([
      loadFolioContentFromIdb(folioId),
      loadRevisionHistory(folioId),
      loadPersonaNotesLocally(folioId),
      loadFoliosFromIdb(),
    ]);
    if ((await loadActiveFolioIdFromIdb()) !== folioId) return;
    if (state.folioId !== folioId) {
      const [notebook, brief] = await Promise.all([
        loadWritingToolsNotebook(folioId),
        loadBriefFromIdb(folioId),
      ]);
      state.notebook = notebook;
      if (!notebook.audience)
