const { spawnSync } = require('node:child_process');
const project = '6759be60-2cfb-4865-b476-93270bf712a3';
const service = '5cc03084-5760-455a-bce5-1d9ea1ee9843';
const environment = 'b40a6501-a61f-47ed-b66f-061677094b9a';
const run = (args, input) => spawnSync('rtk', ['proxy', ...args], { input, encoding: 'utf8', timeout: 45000, maxBuffer: 2 * 1024 * 1024 });
const vars = run(['railway', 'variable', 'list', '--project', project, '--service', service, '--environment', environment, '--json']);
if (vars.status !== 0) { console.error('Could not read gateway configuration; no changes made.'); process.exit(1); }
let current;
try { current = JSON.parse(vars.stdout); } catch { console.error('Could not parse gateway configuration; no changes made.'); process.exit(1); }
if (typeof current.TYPESAFE_API_KEY === 'string' && current.TYPESAFE_API_KEY.trim()) {
  console.log('Gateway already has TYPESAFE_API_KEY. Preserved existing credential.');
  process.exit(0);
}
const secret = run(['skate', 'get', 'typesafe_api_key@secrets']);
if (secret.status !== 0 || !secret.stdout.trim()) { console.error('typesafe_api_key@secrets is unavailable; no changes made.'); process.exit(2); }
const key = secret.stdout.trim();
if (/\s/.test(key)) { console.error('Secret has an unexpected format; no changes made.'); process.exit(2); }
const set = run(['railway', 'variable', 'set', 'TYPESAFE_API_KEY', '--stdin', '--project', project, '--service', service, '--environment', environment, '--skip-deploys'], key);
if (set.status !== 0) { console.error('Gateway credential update failed. Secret output suppressed.'); process.exit(1); }
console.log('Set gateway TYPESAFE_API_KEY from Skate. Automatic deployments disabled.');

