    folioId: input.folioId,
    draftFingerprint: input.fingerprint,
    scoringMethod: "judgement",
    judgementGrade: grade,
    criteria,
    overallScore: overall,
    overallGrade: letter,
    summary: `Judgement marks across ${criteria.length} enabled criteria, weighted equally. Ask the room for an independent reading or generate a written review.`,
    timestamp: grade.at,
    judges: [],
    staticScore: input.staticScore,
    targetFit: grade.criteria.targetFit?.score,
